using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEngine.AI;using Codice.Enemies;using Codice.Bosses;
public static class BuildCemetery {
 const string Out="Assets/Resources/ExpeditionEnemies/Cemetery/";
 static string Find(string token)=>AssetDatabase.FindAssets("t:Model",new[]{"Assets/03_Models/Cemetery"}).Select(AssetDatabase.GUIDToAssetPath).First(p=>p.EndsWith(token,StringComparison.OrdinalIgnoreCase));
 public static string Rigs(){foreach(var token in new[]{"Iron Oath Executioner.fbx","THE STRAW REAPER.fbx","The Watcher of the Hollow Eye.fbx"}){var p=Find(token);var i=(ModelImporter)AssetImporter.GetAtPath(p);i.animationType=ModelImporterAnimationType.Human;i.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;i.SaveAndReimport();}return "Humanoid avatars imported";}
 static Bounds BoundsOf(GameObject g){var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 static void Fit(GameObject v,float height){var b=BoundsOf(v);v.transform.localScale*=height/b.size.y;b=BoundsOf(v);v.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z);}
 static AnimationClip Clip(string path)=>AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().First(c=>!c.name.StartsWith("__"));
 static AnimationClip Human(string state){var c=Resources.Load<AnimatorController>("Presentation/Human/ClassicHuman");var m=c.layers[0].stateMachine.states.First(s=>s.state.name==state).state.motion;if(m is BlendTree bt)m=bt.children.First(t=>t.motion is AnimationClip).motion;return (AnimationClip)m;}
 static AnimatorController Controller(string name,AnimationClip[] clips){string p=Out+name+".controller";var c=AssetDatabase.LoadAssetAtPath<AnimatorController>(p)??AnimatorController.CreateAnimatorControllerAtPath(p);foreach(var s in c.layers[0].stateMachine.states)c.layers[0].stateMachine.RemoveState(s.state);c.parameters=Array.Empty<AnimatorControllerParameter>();foreach(string n in new[]{"Speed","ActionSpeed","LocomotionSpeed"})c.AddParameter(new AnimatorControllerParameter{name=n,type=AnimatorControllerParameterType.Float,defaultFloat=1});string[] names={"Idle","Chase","Patrol","Melee","Shoot","Hit","Stun","Death","Run","Slam","Summon"};for(int i=0;i<names.Length;i++){var st=c.layers[0].stateMachine.AddState(names[i]);var source=clips[Math.Min(i,clips.Length-1)];string cp=Out+name+"_State_"+names[i]+".anim";var copy=AssetDatabase.LoadAssetAtPath<AnimationClip>(cp);if(!copy){copy=UnityEngine.Object.Instantiate(source);AssetDatabase.CreateAsset(copy,cp);}else EditorUtility.CopySerialized(source,copy);copy.name=names[i];AnimationUtility.SetAnimationEvents(copy,Array.Empty<AnimationEvent>());var settings=AnimationUtility.GetAnimationClipSettings(copy);settings.loopTime=i==0||i==1||i==2||i==6||i==8;AnimationUtility.SetAnimationClipSettings(copy,settings);st.motion=copy;st.speedParameterActive=i!=0&&i!=7;st.speedParameter=i==1||i==2||i==8?"LocomotionSpeed":"ActionSpeed";if(i==0)c.layers[0].stateMachine.defaultState=st;}return c;}
 static void Materials(GameObject v,string source,string label){var textures=Directory.GetFiles(Path.GetDirectoryName(source),"*.png",SearchOption.AllDirectories).Concat(Directory.GetFiles(Path.GetDirectoryName(source),"*.tga",SearchOption.AllDirectories)).ToArray();foreach(var r in v.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(old=>{string key=old?old.name:"Surface";string lower=key.ToLowerInvariant();var tex=old?old.mainTexture:null;string match=lower.Contains("eye")?"Eyes":lower.Contains("head")||lower.Contains("cabeza")?"face":lower.Contains("piel")?"piel":lower.Contains("garrote")?"garrote":lower.Contains("ropa baja")?"baja":lower.Contains("cuerpo tela")?"arriba":lower.Contains("metal")?"metal":lower.Contains("wood")?"wood":lower.Contains("shoes")?"shoes":lower.Contains("pants")?"pants":lower.Contains("clothes 2")?"hands":lower.Contains("clothes 1")?"jacket":lower.Contains("brazos")?"manos":lower.Contains("piernas")?"piernas":lower.Contains("cuerpo")?"body":"";var file=textures.FirstOrDefault(t=>match!=""&&Path.GetFileName(t).IndexOf(match,StringComparison.OrdinalIgnoreCase)>=0)??textures.FirstOrDefault();if(!tex&&file!=null)tex=AssetDatabase.LoadAssetAtPath<Texture>(file.Replace('\\','/'));string path=Out+label+"_"+key.Replace('/','_')+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetTexture("_BaseMap",tex);m.SetColor("_BaseColor",label=="Necromancer"?new Color(.64f,.83f,.74f):new Color(.78f,.76f,.72f));m.SetFloat("_Smoothness",.23f);m.SetFloat("_Cull",0);if(label=="Necromancer"){var emission=AssetDatabase.LoadAssetAtPath<Texture>("Assets/Necromanser/Texture/necromant_Body_Emission.tga");if(lower.Contains("body")){m.SetTexture("_EmissionMap",emission);m.SetColor("_EmissionColor",new Color(.08f,.7f,.36f));m.EnableKeyword("_EMISSION");}}EditorUtility.SetDirty(m);return m;}).ToArray();foreach(var sk in v.GetComponentsInChildren<SkinnedMeshRenderer>()){sk.updateWhenOffscreen=true;sk.localBounds=new Bounds(Vector3.up,Vector3.one*12);}}
 }
 public static string Build(){Directory.CreateDirectory(Out);AssetDatabase.Refresh();
  HumanMob("Executioner","Iron Oath Executioner.fbx",2.35f,EnemyKind.Heavy,.9f,1.2f);
  HumanMob("StrawReaper","THE STRAW REAPER.fbx",2.05f,EnemyKind.Swordsman,1.05f,.9f);
  HumanMob("Watcher","The Watcher of the Hollow Eye.fbx",2.45f,EnemyKind.Heavy,.75f,1.4f);
  Spider("HeadSpider","HeadSpider(Unrigged).fbx",.85f,1.4f);Spider("Huntsman","Huntsman_spider(Unrigged).fbx",.65f,1.65f);
  Necromancer();Architecture();Golem();AssetDatabase.SaveAssets();return "Five cemetery mobs, Necromancer, cemetery modules, Golem 2.2m";}
 static GameObject Root(string name,float h,float radius){var g=new GameObject(name);var a=g.AddComponent<NavMeshAgent>();a.height=h;a.radius=radius;a.acceleration=14;var c=g.AddComponent<CapsuleCollider>();c.height=h;c.radius=radius;c.center=Vector3.up*h/2;return g;}
 static void HumanMob(string name,string token,float h,EnemyKind kind,float speed,float health){string src=Find(token);var root=Root(name,h,.5f);try{var v=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(src),root.transform);v.transform.localPosition=Vector3.zero;Fit(v,h);Materials(v,src,name);var a=v.GetComponentInChildren<Animator>();if(!a||!a.avatar||!a.avatar.isValid||!a.avatar.isHuman)throw new Exception("Invalid avatar "+name);var idle=Human("SwordIdle");var run=Human("SwordRun");a.runtimeAnimatorController=Controller(name,new[]{idle,run,run,Human(kind==EnemyKind.Heavy?"HeavyAttack":"SwordCombo1"),Human("StaffCast"),Human("Hit"),Human("Hit"),Human("Death"),run});a.applyRootMotion=false;a.fireEvents=false;var e=root.AddComponent<BasicEnemy>();e.kind=kind;e.variantName=name;e.animator=a;e.useNativeAnimator=true;e.healthMultiplier=health;e.speedMultiplier=speed;e.nativeWindup=kind==EnemyKind.Heavy?1.1f:.65f;PrefabUtility.SaveAsPrefabAsset(root,Out+name+".prefab");}finally{UnityEngine.Object.DestroyImmediate(root);}}
 static void Spider(string name,string token,float h,float speed){var src=Find(token);var root=Root(name,h,.65f);try{var v=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(src),root.transform);v.transform.localPosition=Vector3.zero;Fit(v,h);Materials(v,src,name);var a=v.AddComponent<Animator>();var idle=SpiderClip(v,name,"Idle",false);var walk=SpiderClip(v,name,"Walk",true);var bite=SpiderClip(v,name,"Bite",false);var death=SpiderClip(v,name,"Death",false);a.runtimeAnimatorController=Controller(name,new[]{idle,walk,walk,bite,bite,bite,bite,death,walk});a.fireEvents=false;var e=root.AddComponent<BasicEnemy>();e.kind=EnemyKind.Swordsman;e.variantName=name;e.animator=a;e.useNativeAnimator=true;e.speedMultiplier=speed;e.healthMultiplier=.6f;e.damageMultiplier=.7f;e.nativeWindup=.5f;PrefabUtility.SaveAsPrefabAsset(root,Out+name+".prefab");}finally{UnityEngine.Object.DestroyImmediate(root);}}
 static AnimationClip SpiderClip(GameObject v,string name,string state,bool walking){var clip=new AnimationClip{name=state,frameRate=30};float duration=state=="Death"?3:1;foreach(var t in v.GetComponentsInChildren<Transform>().Where(t=>t!=v.transform&&t.parent==v.transform)){string p=AnimationUtility.CalculateTransformPath(t,v.transform);var angles=t.localEulerAngles;float amplitude=state=="Death"?75:state=="Bite"?22:walking?6:1.5f;var keys=new System.Collections.Generic.List<Keyframe>();for(int n=0;n<=30;n++){float f=n/30f;keys.Add(new Keyframe(f*duration,angles.x+(state=="Death"?Mathf.SmoothStep(0,amplitude,Mathf.Min(1,f*3)):Mathf.Sin(f*Mathf.PI*2)*amplitude)));}clip.SetCurve(p,typeof(Transform),"localEulerAnglesRaw.x",new AnimationCurve(keys.ToArray()));}var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=state=="Idle"||walking;AnimationUtility.SetAnimationClipSettings(clip,settings);string path=Out+name+"_"+state+".anim";var prior=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);if(prior){EditorUtility.CopySerialized(clip,prior);UnityEngine.Object.DestroyImmediate(clip);return prior;}AssetDatabase.CreateAsset(clip,path);return clip;}
 static void Necromancer(){var root=Root("Necromancer",2.8f,.7f);try{string src="Assets/Necromanser/Prefab/Necromanser Prefab.prefab";var v=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(src),root.transform);v.transform.localPosition=Vector3.zero;Fit(v,2.8f);Materials(v,"Assets/Necromanser/Texture/necromant_Body_Albedo.tga","Necromancer");var a=v.GetComponentInChildren<Animator>();Func<string,AnimationClip> c=n=>Clip("Assets/Necromanser/Animations/Necromancer@"+n+".fbx");a.runtimeAnimatorController=Controller("Necromancer",new[]{c("idle1"),c("walk"),c("walk"),c("atack1"),c("spellcast1"),c("getgit"),c("wound"),c("death"),c("walk"),c("atack2"),c("roar")});a.applyRootMotion=false;a.fireEvents=false;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;var b=root.AddComponent<BossCharacter>();b.kind=BossKind.Necromancer;b.visual=v.transform;b.useNativeAnimator=true;b.baseHealth=2200;b.goldReward=650;b.summons=new[]{Resources.Load<BasicEnemy>("ExpeditionEnemies/CryptSkeleton"),AssetDatabase.LoadAssetAtPath<BasicEnemy>(Out+"StrawReaper.prefab")};PrefabUtility.SaveAsPrefabAsset(root,"Assets/Resources/ExpeditionEnemies/Necromancer.prefab");}finally{UnityEngine.Object.DestroyImmediate(root);}}
 static void Architecture(){string src="Assets/03_Models/StructuresItemsInMap/KayKit_HalloweenBits_1.0_FREE/Assets/fbx(unity)/";foreach(var pair in new[]{new[]{"grave_A","Grave"},new[]{"grave_A_destroyed","GraveBroken"}}){var model=AssetDatabase.LoadAssetAtPath<GameObject>(src+pair[0]+".fbx");var g=UnityEngine.Object.Instantiate(model);g.transform.position=Vector3.zero;Fit(g,1.5f);foreach(var r in g.GetComponentsInChildren<Renderer>())r.sharedMaterial=Resources.Load<Material>("CindersStone/Wall");foreach(var mf in g.GetComponentsInChildren<MeshFilter>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;PrefabUtility.SaveAsPrefabAsset(g,"Assets/Resources/GothicArchitecture/"+pair[1]+".prefab");UnityEngine.Object.DestroyImmediate(g);}var fence=new GameObject("CemeteryFence");for(int i=0;i<9;i++){var bar=GameObject.CreatePrimitive(PrimitiveType.Cube);bar.transform.SetParent(fence.transform);bar.transform.localPosition=new Vector3(-2+i*.5f,1.3f,0);bar.transform.localScale=new Vector3(.07f,2.6f,.08f);bar.GetComponent<Renderer>().sharedMaterial=Resources.Load<Material>("CindersStone/Wall");}var collider=fence.AddComponent<BoxCollider>();collider.size=new Vector3(4,2.6f,.15f);collider.center=Vector3.up*1.3f;PrefabUtility.SaveAsPrefabAsset(fence,"Assets/Resources/GothicArchitecture/CemeteryFence.prefab");UnityEngine.Object.DestroyImmediate(fence);}
 static void Golem(){string path="Assets/Resources/ExpeditionEnemies/MuckResidents/Golem funerario.prefab";var g=PrefabUtility.LoadPrefabContents(path);try{var v=g.GetComponentInChildren<Animator>().gameObject;Fit(v,2.2f);var a=g.GetComponent<NavMeshAgent>();a.height=2.2f;a.radius=.6f;var c=g.GetComponent<CapsuleCollider>();c.height=2.2f;c.radius=.6f;c.center=Vector3.up*1.1f;PrefabUtility.SaveAsPrefabAsset(g,path);}finally{PrefabUtility.UnloadPrefabContents(g);}}
}
